def is_new_producer_contract(name: str) -> bool:
    lifecycle = CONTRACT_LIFECYCLE.get(name)
    return lifecycle is not None and lifecycle["new_producer"] == "allowed"

def require_new_producer_contract(name: str) -> None:
    if is_new_producer_contract(name):
        return
